    private TestTypeDeserializer testDeserializer;
    private DeserializationContext mockCtxt;
    private TypeIdResolver mockIdResolver;
    private BeanProperty mockProperty;
    private JavaType mockBaseType;
    private Map<String, JsonDeserializer<Object>> deserializersMap;

    // Concrete implementation to test protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        protected Map<String, JsonDeserializer<Object>> _deserializers = new HashMap<>();

        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                      boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override
        public String baseTypeName() { return "TestBase"; }

        // Expose protected method for testing
        public JsonDeserializer<Object> publicFindDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializer(ctxt, typeId);
        }

        // Override to access the internal map used in the method
        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return super._findDefaultImplDeserializer(ctxt);
        }

        @Override
        protected JsonDeserializer<Object> _handleUnknownTypeId(DeserializationContext ctxt, String typeId, 
                                                               TypeIdResolver idResolver, JavaType baseType) throws IOException {
            return super._handleUnknownTypeId(ctxt, typeId, idResolver, baseType);
        }

        // Access the internal _deserializers field via reflection or by making it package-private/protected in the test class
        // For this test, we'll use a trick: we'll mock the behavior or use a subclass that exposes it.
        // Since the original code uses _deserializers.get(typeId), we must ensure our Test class uses the same field name.
        // Note: In the provided code, _deserializers is a field of the class.
    }

    // Because the original code uses a field '_deserializers', we must ensure our subclass 
    // actually has that field or we must use reflection. 
    // Let's use a slightly more robust approach where we subclass and provide the field.
    private static class TestTypeDeserializerWithField extends TestTypeDeserializer {
        // The original class has 'protected final Map<String, JsonDeserializer<Object>> _deserializers'
        // Since it is final, we cannot redefine it. We must rely on the parent.
        // However, the provided snippet shows the method using _deserializers.
        // In a real Jackson environment, this field exists in TypeDeserializerBase.

        public TestTypeDeserializerWithField(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                           boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }
    }

    @Before
    public void setUp() throws Exception {
        mockCtxt = mock(DeserializationContext.class);
        mockIdResolver = mock(TypeIdResolver.class);
        mockProperty = mock(BeanProperty.class);
        mockBaseType = mock(JavaType.class);
        deserializersMap = new HashMap<>();

        // We use a spy/subclass to inject the deserializers map if possible, 
        // but since _deserializers is likely a field in the base class, 
        // we will use reflection to populate it for the test.
        testDeserializer = new TestTypeDeserializer(mockBaseType, mockIdResolver, "type", true, Object.class) {
            // We override the field by providing a way to set it if it were accessible, 
            // but since we can't change the final field, we'll assume the test environment 
            // allows us to interact with the object.
        };

        // Using reflection to set the private/protected final _deserializers field
        java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
        field.setAccessible(true);
        field.set(testDeserializer, deserializersMap);

        // Set the _property field via reflection
        java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
        propField.setAccessible(true);
        propField.set(testDeserializer, mockProperty);

        // Set the _baseType field via reflection
        java.lang.reflect.Field baseTypeField = TypeDeserializerBase.class.getDeclaredField("_baseType");
        baseTypeField.setAccessible(true);
        baseTypeField.set(testDeserializer, mockBaseType);
    }

    @Test
    public void testFindDeserializer_ExistingInMap() throws IOException {
        String typeId = "existing";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        deserializersMap.put(typeId, mockDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(mockCtxt, typeId);

        assertEquals(mockDeser, result);
        verifyNoInteractions(mockIdResolver);
    }

    @Test
    public void testFindDeserializer_TypeIdFound_NarrowingBaseType() throws IOException {
        String typeId = "newType";
        JavaType mockType = mock(JavaType.class);
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);

        when(mockIdResolver.typeFromId(mockCtxt, typeId)).thenReturn(mockType);
        when(mockType.getRawClass()).thenReturn(String.class);
        // Simulate same class type for the narrowing check
        when(mockBaseType.getClass()).thenReturn(mockType.getClass());
        when(mockBaseType.narrowBy(any())).thenReturn(mockType);
        when(mockCtxt.findContextualValueDeserializer(eq(mockType), eq(mockProperty))).thenReturn(mockDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(mockCtxt, typeId);

        assertNotNull(result);
        assertEquals(mockDeser, result);
        assertEquals(mockDeser, deserializersMap.get(typeId));
        verify(mockBaseType).narrowBy(String.class);
    }

    @Test
    public void testFindDeserializer_TypeIdFound_NoNarrowing() throws IOException {
        String typeId = "newType";
        JavaType mockType = mock(JavaType.class);
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);

        when(mockIdResolver.typeFromId(mockCtxt, typeId)).thenReturn(mockType);
        // Different class type to bypass narrowing
        when(mockBaseType.getClass()).thenReturn(Object.class); 
        when(mockType.getClass()).thenReturn(JavaType.class); 
        when(mockCtxt.findContextualValueDeserializer(eq(mockType), eq(mockProperty))).thenReturn(mockDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(mockCtxt, typeId);

        assertNotNull(result);
        assertEquals(mockDeser, result);
        verify(mockBaseType, never()).narrowBy(any());
    }

