        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);

        when(mockIdResolver.typeFromId(mockCtxt, typeId)).thenReturn(null);

        // We need to handle the protected _findDefaultImplDeserializer. 
        // Since we can't easily mock a protected method of the class under test, 
