        // Because we can't easily mock the method inside the same class, we use a Spy.
        TypeDeserializerBase spyDeserializer = spy(testDeserializer);
        doReturn(mockDeser).when(spyDeserializer)._findDefaultImplDeserializer(mockCtxt);

        // We need to call the method on the spy, but the method is final. 
